export const AREAS = [...new Set(INSTRUMENTS.map((i) => i.area))];
export const byArea = (area) => INSTRUMENTS.filter((i) => i.area === area);

// ---- THE SUITE'S OWN CHECKS, MADE FINDABLE (v2883) ---------------------------------------------------------------
//
// WHY THIS EXISTS, AND IT IS A CORRECTION. In v2881 I rebuilt an SPH hydrostatic check that ALREADY EXISTED,
// passing, in tools/ship/physicsSuite.mjs -- and wrote into the changelog that "the recorded diagnosis was wrong"
// when the record was right and I had not read it. I had read the one-line summary in the UNGATED list and never
// the note attached to the gated check twenty lines below.
//
// THE INSTRUMENTS INDEX MADE THE PAGES FINDABLE AND LEFT THIRTY-EIGHT CHECKS INVISIBLE. Those checks are where
// most of the exact keys in this engine actually live -- the speed of sound to the fifth decimal, Rayleigh's
// 1708, a shock compressing by exactly six -- and the only way to know whether one exists was to read a
// thousand-line file. That is not a searchable inventory, it is a haystack.
//
// So: CHECKS is already exported from the suite. Surfacing its names and exact statements costs nothing and
// makes "does a check for X already exist?" answerable by looking rather than by remembering.
export async function suiteChecks() {
    const { CHECKS, UNGATED } = await import("../tools/ship/physicsSuite.mjs");
    return {
        gated: CHECKS.map((c) => ({ name: c.name, exact: c.exact, tol: c.tol })),
        ungated: (UNGATED || []).map((t) => String(t)),
    };
}

// ---- MAKING THE KEYS CHECKABLE, NOT MERELY PRESENT (v2887) --------------------------------------------------------
//
// v2884 taught this the hard way and v2886 paid for it: A GATE CAN ENFORCE THAT A CLAIM IS PRESENT AND STILL LET
// A FALSE CLAIM THROUGH. The mutation table's duplicate-match declaration was checked for EXISTENCE, passed, and
// was backwards -- and that inverted note stood as documented fact until someone applied the mutation and
// measured whether anything moved.
//
// instruments-selfcheck had exactly the same shape: it asserted every entry names an exact key, and that the key
// cites a number rather than an adjective. It never asked whether the number was TRUE. Auditing all 24 found one
// that was not: the spatial-agreement entry claimed "156 pairs at n=200", which is the gap at n=120 with r=2.
// A real measurement, confidently stated, attached to the wrong configuration.
//
// So: an entry may carry a VERIFIER. It recomputes the cited quantity from the live instrument and reports what
// it actually is. The gate runs every one that exists and fails on a mismatch -- which turns the index from a
// description into a measurement. Not every key can be checked cheaply (a lattice run is seconds to minutes, and
// a gate nobody can afford to run is a gate nobody runs), so this covers the fast ones and says so.
export const KEY_VERIFIERS = {
    "kepler": async () => {
        const K = await import("../physics/orbits/kepler.js");
        const F = await import("../physics/discovery/symbolicFit.js");
        const a = [1, 1.3, 1.7, 2.2, 2.9, 3.8, 5.0, 6.5];
        const got = F.powerLaw(a, a.map((v) => K.period(v, 1))).exponent;
        return { quantity: "log T vs log a slope", claimed: 1.5, actual: got, ok: Math.abs(got - 1.5) < 1e-12 };
    },
    "splat-lab": async () => {
        const S = await import("../physics/splat/gaussianSplat.js");
        const got = S.areaDepthSlope([2, 3, 5, 8, 13, 21]);
        return { quantity: "log area vs log depth slope", claimed: -2, actual: got, ok: Math.abs(got + 2) < 1e-12 };
    },
    "probe-lab": async () => {
        const P = await import("../physics/blackhole/probe.js");
        const got = P.arcsecPerCentury(P.precessionExact(1476.6, 5.7909e10, 0.20563), 87.9691);
        return { quantity: "Mercury precession, arcsec/century", claimed: 43, actual: got, ok: Math.abs(got - 43) < 0.5 };
    },
    "geodesic": async () => {
        const G = await import("../physics/blackhole/geodesic.js");
        const got = G.criticalImpact(1);
        return { quantity: "shadow edge / M", claimed: 3 * Math.sqrt(3), actual: got, ok: Math.abs(got - 3 * Math.sqrt(3)) < 1e-11 };
    },
    "fresnel": async () => {
        const O = await import("../physics/optics/fresnel.js");
        const got = O.knifeEdgeIntensity(0);
        return { quantity: "knife-edge intensity at the shadow boundary", claimed: 0.25, actual: got, ok: Math.abs(got - 0.25) < 1e-12 };
    },
    // v4314 -- CALLS THE CPU PORT RATHER THAN RE-DERIVING THE LOOP. render/swiftShaderModel.mjs is the reference
    // the shader is graded against; re-typing its iteration here would be a second copy of the arithmetic, and
    // a second copy is never the one that gets updated. WHAT THIS DOES NOT VERIFY, stated rather than implied:
    // the GPU. Node has no WebGL2 context, so the claim "the FRAGMENT reads ln 2" is checked by
    // tools/ship/swiftShaders-selfcheck.mjs in a real browser and by the page itself; this verifies that the
    // key attached to the entry is the number the model produces.
    "krbn-lyapunov": async () => {
        const M = await import("../render/swiftShaderModel.mjs");
        const H = 64, img = { w: 1, h: H, premultiplied: true, data: new Float32Array(H * 4).fill(1) };
        const out = M.swkLyapunov(img, { rLo: 4, rHi: 4, raw: true });
        const lam = [];
        for (let y = 0; y < H; y++) lam.push((out.data[y * 4] + out.data[y * 4 + 1] / 255) * 4 - 3);
        lam.sort((a, b) => a - b);
        const got = lam[H >> 1];
        // 1e-3, not 1e-2: the measured error is 2.1e-4, so a 1e-2 tolerance would have been fifty times the
        // slack the measurement needs and would pass a model that had lost three digits. Not tightened to the
        // measured value either -- the CPU port is deterministic, but pinning 2.1e-4 would make a Math.log
        // implementation difference read as a broken instrument.
        return { quantity: "Lyapunov exponent at r=4, median over " + H + " seeds, from the CPU port the shader is graded against",
                 claimed: Math.LN2, actual: got, ok: Math.abs(got - Math.LN2) < 1e-3 };
    },
    "logistic": async () => {
        const L = await import("../physics/chaos/logistic.js");
        const got = L.lyapunov(4);
        return { quantity: "Lyapunov exponent at r=4", claimed: Math.LN2, actual: got, ok: Math.abs(got - Math.LN2) < 1e-5 };
    },
    "spatial-agreement": async () => {
        const A = await import("../physics/spatial/agreement.mjs");
        const p = A.scene(200, { span: 10 });
        const got = A.bruteBox(p, 1.2).size - A.bruteSphere(p, 1.2).size;
        // THE ONE THAT WAS WRONG. Claimed 156; 156 is the n=120 r=2 scene. At n=200 with r=1.2 it is 100.
        return { quantity: "Chebyshev-near but Euclidean-far pairs at n=200, r=1.2", claimed: 100, actual: got, ok: got === 100 };
    },
    "discovery-lab": async () => {
        const F = await import("../physics/discovery/symbolicFit.js");
        const K = await import("../physics/orbits/kepler.js");
        const a = [1, 1.3, 1.7, 2.2, 2.9, 3.8, 5.0, 6.5];
        const got = F.powerLaw(a, a.map((v) => K.period(v, 1))).exponent;
        return { quantity: "rediscovered Kepler exponent", claimed: 1.5, actual: got, ok: Math.abs(got - 1.5) < 1e-9 };
    },
};

/** Run every verifier that exists. The ones without are named, so the gap is visible rather than assumed away. */
export async function verifyKeys() {
    const checked = [], unchecked = [];
    for (const inst of INSTRUMENTS) {
        const v = KEY_VERIFIERS[inst.id];
        if (!v) { unchecked.push(inst.id); continue; }
        try { checked.push({ id: inst.id, ...(await v()) }); }
        catch (e) { checked.push({ id: inst.id, ok: false, error: String((e && e.message) || e) }); }
    }
    return { checked, unchecked, mismatches: checked.filter((c) => !c.ok) };
}
